sections.body:
Here's the real power: keep the data in an array and **draw** the screen from the array. The function that does this is usually called `render`. Every time it's called, it clears the list and rebuilds it from the array:

```js
const items = ["Oxygen", "Water", "Fuel"];

function render() {
  list.textContent = ""; // clear first
  for (const item of items) {
    const li = document.createElement("li");
    li.textContent = item;
    list.append(li);
  }
}

render();
items.push("Shield"); // the data changed...
render();             // ...draw the screen again
```

The rule is simple: **change the data first, then call `render()`.** If you forget to clear, the list is added again on every call.

examples.code:
const planets = ["Mercury", "Venus", "Earth", "Mars"];
const list = document.querySelector("#list");

for (const name of planets) {
  const li = document.createElement("li");
  li.textContent = name;
  list.append(li);
}

const sun = document.createElement("li");
sun.textContent = "Sun (center)";
sun.classList.add("sun");
list.prepend(sun);
console.log("Number of items:", list.children.length);

const stars = ["Vega", "Sirius"];
const list = document.querySelector("#list");

function render() {
  list.textContent = "";
  stars.forEach((star, i) => {
    const li = document.createElement("li");
    li.textContent = star + " ";
    const del = document.createElement("button");
    del.textContent = "Delete";
    del.dataset.index = i;
    li.append(del);
    list.append(li);
  });
}

list.addEventListener("click", (e) => {
  if (e.target.tagName !== "BUTTON") return;
  stars.splice(Number(e.target.dataset.index), 1);
  render();
});

document.querySelector("#add").addEventListener("click", () => {
  stars.push("Star " + Math.floor(Math.random() * 100));
  render();
});

render();

