  for (const part of parts) {
    // create an <li>: write the name, put the ID in dataset.id
    const li = document.createElement("li");
    li.textContent = part.name;
    li.dataset.id = part.id;
    cargo.append(li);
  }
}

render();

// click listener on #cargo
