challenge.solution:
const items = ["Oxygen", "Water", "Fuel"];
const cargo = document.querySelector("#cargo");
const input = document.querySelector("#item-name");

function render() {
  cargo.textContent = "";
  items.forEach((item, i) => {
    const li = document.createElement("li");
    li.textContent = item;
    // Delete button: class "del", dataset.index = i
    const del = document.createElement("button");
    del.textContent = "Delete";
    del.classList.add("del");
    del.dataset.index = i;
    li.append(del);
    cargo.append(li);
  });
  document.querySelector("#count").textContent = `${items.length} items`;
}

render();

// the Add button
document.querySelector("#add").addEventListener("click", () => {
  const name = input.value.trim();
  if (name === "") return;
  items.push(name);
  input.value = "";
  render();
});

// the Delete buttons (event delegation)
cargo.addEventListener("click", (e) => {
  if (!e.target.classList.contains("del")) return;
  items.splice(Number(e.target.dataset.index), 1);
  render();
});

