const inventory = ["shield", "laser", "map"];

// (Day 14) the Start button opens the game panel
document.querySelector("#start-btn").addEventListener("click", () => {
  document.querySelector("#start-screen").classList.add("hidden");
  document.querySelector("#game-panel").classList.remove("hidden");
});

function renderInventory() {
  const list = document.querySelector("#inventory");
  // clear, an <li class="item"> for every thing
  list.textContent = "";
  for (const thing of inventory) {
    const li = document.createElement("li");
    li.textContent = thing;
    li.classList.add("item");
    list.append(li);
  }
}

renderInventory();
